        $digits[] = 2;
        $primeExponents[2] -= 3;
    }

    rsort($digits);
    echo implode('', $digits);
}

function getFactorialExponents($d) {
    $exponents = [2 => 0, 3 => 0, 5 => 0, 7 => 0];
    for ($i = 2; $i <= $d; $i++) {
        $current = $i;
        while ($current % 2 == 0) {
            $exponents[2]++;
            $current /= 2;
        }
        while ($current % 3 == 0) {
            $exponents[3]++;
            $current /= 3;
        }
