    $digitExponents[$d] = [
        2 => 0,
        3 => 0,
        5 => 0,
        7 => 0
    ];
    // Calculate exponents for d!
    $fact = 1;
    for ($i = 1; $i <= $d; $i++) {
        $fact *= $i;
    }
    // Factorize fact into primes 2,3,5,7
    $temp = $fact;
    foreach ([2,3,5,7] as $p) {
        $count = 0;
        while ($temp % $p == 0) {
            $count++;
            $temp /= $p;
        }
        $digitExponents[$d][$p] = $count;
    }
}

// Sum exponents from all digits in a
$totalExponents = [2 => 0, 3 => 0, 5 => 0, 7 => 0];
for ($i = 0; $i < $n; $i++) {
    $d = intval($a[$i]);
    foreach ([2,3,5,7] as $p) {
        $totalExponents[$p] += $digitExponents[$d][$p];
    }
}

// Generate candidate digits in descending order
$candidates = [9,8,7,6,5,4,3,2];
$result = '';

