    if ($d < 2) continue;
    $factExponents = getExponents($d);
    foreach ($factExponents as $p => $e) {
        $primeExponents[$p] += $e;
    }
}

$x = constructMaxNumber($primeExponents);
echo $x . "\n";

function getExponents($d) {
    $exponents = [2 => 0, 3 => 0, 5 => 0, 7 => 0];
    for ($i = 2; $i <= $d; $i++) {
        $num = $i;
        while ($num % 2 == 0) { $exponents[2]++; $num /= 2; }
        while ($num % 3 == 0) { $exponents[3]++; $num /= 3; }
        while ($num % 5 == 0) { $exponents[5]++; $num /= 5; }
        while ($num % 7 == 0) { $exponents[7]++; $num /= 7; }
    }
    return $exponents;
}

function constructMaxNumber($primeExponents) {
    $digits = [];
    while ($primeExponents[2] > 0 || $primeExponents[3] > 0 || $primeExponents[5] > 0 || $primeExponents[7] > 0) {
        if (canUseDigit(7, $primeExponents)) {
            $digits[] = 7;
            subtractExponents(7, $primeExponents);
        } else if (canUseDigit(5, $primeExponents)) {
            $digits[] = 5;
            subtractExponents(5, $primeExponents);
        } else if (canUseDigit(4, $primeExponents)) {
            $digits[] = 4;
            subtractExponents(4, $primeExponents);
        } else if (canUseDigit(3, $primeExponents)) {
            $digits[] = 3;
            subtractExponents(3, $primeExponents);
        } else if (canUseDigit(2, $primeExponents)) {
            $digits[] = 2;
            subtractExponents(2, $primeExponents);
        } else {
            break;
        }
    }
    rsort($digits);
    return implode('', $digits);
}

function canUseDigit($d, $exponents) {
    $required = getExponents($d);
    foreach ($required as $p => $e) {
        if ($exponents[$p] < $e) return false;
    }
    return true;
}

